<script setup>import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const p=defineProps({question:Object,canManage:Boolean,statuses:Array});const reply=useForm({body:'',images:[]});const send=()=>reply.post(`/questions/${p.question.id}/replies`,{forceFormData:true,onSuccess:()=>reply.reset()});const status=useForm({status:p.question.status});</script>
<template><AppLayout><Head :title="question.subject||'پرسش'"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><p class="text-sm text-teal-700">{{question.lesson.course.title}} / {{question.lesson.title}}</p><h1 class="mt-2 text-xl font-bold">{{question.subject||'بدون موضوع'}}</h1><div class="mt-4 rounded-xl bg-slate-50 p-4"><strong>{{question.student.first_name}} {{question.student.last_name}}</strong><p class="mt-2 whitespace-pre-line">{{question.body}}</p><a v-for="f in question.attachments" :href="`/question-attachments/${f.id}`" class="mt-2 block text-sm text-teal-700">{{f.original_name}}</a></div></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">گفت‌وگو</h2><article v-for="r in question.replies" :key="r.id" class="mt-3 rounded-xl border p-4" :class="r.is_staff?'border-teal-200':''"><div class="flex justify-between text-sm"><strong>{{r.user.first_name}} {{r.user.last_name}} <span class="text-xs text-slate-500">{{r.is_staff?'پشتیبانی':'هنرجو'}}</span></strong><time>{{new Date(r.created_at).toLocaleString('fa-IR')}}</time></div><p class="mt-2 whitespace-pre-line">{{r.body}}</p><a v-for="f in r.attachments" :href="`/question-attachments/${f.id}`" class="mt-2 block text-sm text-teal-700">{{f.original_name}}</a></article><form v-if="question.status!=='CLOSED'" class="mt-5 space-y-3" @submit.prevent="send"><textarea v-model="reply.body" rows="4" placeholder="متن پاسخ" class="w-full rounded-xl border p-3"></textarea><input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="reply.images=[...$event.target.files]"><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">ثبت پاسخ</button><p class="text-sm text-red-600">{{reply.errors.body||reply.errors.images}}</p></form><p v-else class="mt-4 text-sm text-slate-500">این گفت‌وگو بسته شده است.</p></section><section class="rounded-2xl border bg-white p-5"><form class="flex gap-3" @submit.prevent="status.patch(`/questions/${question.id}/status`)"><select v-model="status.status"><option v-for="s in statuses" :value="s.value" :disabled="!canManage&&s.value!=='RESOLVED'">{{s.label}}</option></select><button class="rounded-xl border px-4 py-2">تغییر وضعیت</button></form></section></div></AppLayout></template>
